INSERT INTO exams (subject, exam_level, exam_name, description) VALUES
  ('MATH', '100', 'MATH 120 Fundamentals of College Algebra Exam', 'Equations, functions, and graphing at the college algebra level.'),
  ('MATH', '200', 'MATH 181 Calculus I Exam', 'Limits, derivatives, and an introduction to integration.'),
  ('STAT', '100', 'STAT 152 Introduction to Statistics Exam', 'Descriptive statistics, probability, and hypothesis testing.'),
  ('ENG', '100', 'ENG 101 Composition Proficiency Exam', 'Timed essay assessing thesis, organization, and grammar.'),
  ('ENG', '100', 'ENG 102 Argumentation Exam', 'Timed argumentative essay with source analysis.'),
  ('BIOL', '100', 'BIOL 189 Biology Lab Practical', 'Hands-on identification and lab technique assessment.'),
  ('CHEM', '100', 'CHEM 121 General Chemistry I Exam', 'Stoichiometry, atomic structure, and chemical bonding.'),
  ('PHYS', '200', 'PHYS 151 Physics I Exam', 'Kinematics, forces, energy, and momentum.'),
  ('HIST', '100', 'HIST 101 US History Exam', 'Survey of United States history through Reconstruction.'),
  ('PSY', '100', 'PSY 101 Introduction to Psychology Exam', 'Major theories, research methods, and subfields of psychology.'),
  ('CS', '100', 'CS 135 Programming Fundamentals Exam', 'Variables, control flow, functions, and basic data structures.'),
  ('CS', '200', 'CS 202 Data Structures Exam', 'Lists, trees, hash tables, and algorithm analysis.'),
  ('CIT', '100', 'CIT 111 Introduction to IT Exam', 'Hardware, networking basics, and operating systems.'),
  ('SPAN', '100', 'SPAN 101 Elementary Spanish Exam', 'Vocabulary, grammar, and short conversational prompts.'),
  ('ECON', '200', 'ECON 261 Microeconomics Exam', 'Supply and demand, market structures, and consumer choice.');
